#include <bits/stdc++.h>
using namespace std;
#define ll long long


struct FenwickTree {
  int n;
  vector<ll> tree;
  FenwickTree(int n) : n(n), tree(n + 1, 0){}
  void add(int i, ll delta) {
      for(;i <= n; i+=i & -i) tree[i]+=delta;
  }
  ll query(int i) const {
      ll sum = 0;
      for(;i > 0; i -= i & -i) sum += tree[i];
      return sum;
  }
};

ll f(int a, int b, const FenwickTree& bit, int n) {
    return 2 * bit.query(a) + bit.query(a + 2*b) + 3* bit.query(3*n-2*a-b);
}


void solve(){
    int n;
    cin>>n;
    vector<ll> v(3*n);
    for(int i = 0; i < 3*n; i++) cin >> v[i];
    sort(v.rbegin(),v.rend());
    
    FenwickTree bit(3 * n);
    for(int i = 0; i < 3 * n; i++) {
        bit.add(i + 1, v[i]);
    }
    
    ll best = 0;
    int b = n;
    for(int a = 0; a <= n; a++){
        b = min(b, n - a);
        while(b > 0 && f(a, b - 1, bit, n) >= f(a, b, bit, n)) {
            b--;
        }
        best = max(best, f(a, b, bit, n));
    }
    
    cout << best << endl;
}

int main() {
	// your code goes here
	int t;
	cin >> t;
	while(t--){
	    solve();
	}
	return 0;

}
